<script setup lang="ts">
import GlassSchedule from './GlassSchedule.vue'
import { ref, computed } from 'vue'
import { Download, Search } from 'lucide-vue-next'
import { useWorkshop } from '../store'
import { categories, labels, mm, type Category } from '../types'
import { download, csv } from '../export'
const s=useWorkshop(),filter=ref(''),query=ref(''),materialTab=ref('profile')
const parts=computed(()=>s.geometry?.parts.filter(p=>(!filter.value||p.category===filter.value)&&`${p.id} ${p.label} ${p.stock_key}`.includes(query.value))??[])
function exportCsv(){if(!s.geometry)return;download(`${s.project!.name}-构件清单.csv`,csv([['编号','类别','位置','原料型号','数量','长边mm','短边mm','条宽mm','端切角度','中心Xmm','中心Ymm(向下)','起点Xmm','起点Ymm','终点Xmm','终点Ymm'],...s.geometry.parts.map(p=>[p.id,p.category_label,p.label,p.stock_key,p.quantity,mm(p.length),mm(p.short_length),mm(p.width),p.angle,mm(p.center[0]!),mm(p.center[1]!),...(p.start?.map(mm)??['','']),...(p.end?.map(mm)??['',''])])]),'text/csv;charset=utf-8')}
</script>
<template><div class="materials-view"><el-tabs v-model="materialTab" class="workspace-tabs no-print" aria-label="材料类型"><el-tab-pane label="型材清单" name="profile"/><el-tab-pane label="玻璃清单" name="glass"/></el-tabs><GlassSchedule v-show="materialTab==='glass'"/><section v-show="materialTab==='profile'" class="table-panel"><div class="panel-heading"><div><span class="eyebrow">MATERIAL SCHEDULE</span><h2>构件下料清单 <small>{{s.geometry?.count}} 根</small></h2></div><el-button @click="exportCsv"><Download :size="15"/> 导出完整 CSV</el-button></div><div class="table-controls"><el-select v-model="filter" placeholder="全部材料" clearable><el-option v-for="c in categories" :key="c" :value="c" :label="labels[c]"/></el-select><el-input v-model="query" placeholder="搜索编号、位置或型号" clearable><template #prefix><Search :size="15"/></template></el-input></div><div class="filter-summary"><span>显示 {{parts.length}} 项构件</span><el-button v-if="filter||query" text @click="filter='';query=''">清除筛选</el-button></div>
<el-table class="desktop-data" :data="parts" stripe height="570" row-key="id"><el-table-column prop="id" label="构件编号" min-width="175"/><el-table-column prop="category_label" label="材料类别" width="110"/><el-table-column prop="label" label="位置" width="100"/><el-table-column prop="stock_key" label="原料型号" min-width="145"/><el-table-column prop="quantity" label="数量" width="65"/><el-table-column label="长边 / mm" width="110"><template #default="{row}"><b>{{mm(row.length)}}</b></template></el-table-column><el-table-column label="短边 / mm" width="110"><template #default="{row}">{{mm(row.short_length)}}</template></el-table-column><el-table-column label="条宽 / mm" width="95"><template #default="{row}">{{mm(row.width)}}</template></el-table-column><el-table-column label="端切" width="70"><template #default="{row}">{{row.angle}}°</template></el-table-column><el-table-column label="中心坐标 (X, Y) / mm" min-width="175"><template #default="{row}">{{mm(row.center[0])}}, {{mm(row.center[1])}}</template></el-table-column></el-table>
<div class="mobile-data part-cards"><el-empty v-if="!parts.length" description="没有匹配的构件"/><article v-for="p in parts" :key="p.id" class="mobile-card"><div class="card-title"><b>{{p.category_label}} · {{p.label}}</b><el-tag>{{p.quantity}} 根</el-tag></div><div class="card-length">{{mm(p.length)}} <small>mm 长边</small></div><dl><dt>编号</dt><dd>{{p.id}}</dd><dt>原料型号</dt><dd>{{p.stock_key}}</dd><dt>短边 / 条宽</dt><dd>{{mm(p.short_length)}} / {{mm(p.width)}} mm</dd><dt>端切角度</dt><dd>{{p.angle}}°</dd><dt>中心坐标</dt><dd>{{mm(p.center[0]!)}}, {{mm(p.center[1]!)}} mm</dd></dl></article></div>
<p class="table-footnote">外框按长尖端到长尖端计长，短边同时列出。坐标采用左上角原点、Y 向下；玻璃可见开口不作为玻璃下料尺寸。</p></section></div></template>
